CREATE PROCEDURE plus_one(x INT64)
RETURNS result INT64
AS {
  RETURN x + 1 AS result
}

CREATE PROCEDURE greet(name STRING, prefix STRING DEFAULT 'hi')
RETURNS message STRING
AS {
  RETURN prefix || name AS message
}

NODE VALUE score SumAgg<INT64> = 0
MATCH (s:Person)-[:KNOWS]->(t:Person)
PER PATH {
  SET t.@score += 1
}
MATCH (n:Person)
PER NODE (n) {
  RETURN n.id AS id, n.@score AS score
}

MATCH (p:Person)
WHERE EXISTS {
  MATCH (p)-[:KNOWS]->(:Person)
}
RETURN p AS person
